+import { createServer, IncomingMessage, ServerResponse } from "http";
+import { getPendingNotifications, acknowledgeNotifications } from "./notifications.ts";
+
+const PORT = process.env.API_PORT || 3000;
+
+type Handler = (req: IncomingMessage, res: ServerResponse) => Promise<void>;
+
+const sendJson = (res: ServerResponse, status: number, data: unknown): void => {
+  res.writeHead(status, { "Content-Type": "application/json" });
+  res.end(JSON.stringify(data));
+};
+
+const sendError = (res: ServerResponse, status: number, message: string): void => {
+  sendJson(res, status, { error: message });
+};
+
+const handlers: Record<string, Handler> = {
+  "GET /notifications": async (_req, res) => {
+    try {
+      const notifications = await getPendingNotifications();
+      sendJson(res, 200, { notifications });
+    } catch (err) {
+      sendError(res, 500, `Failed to fetch notifications: ${err}`);
+    }
+  },
+
+  "POST /notifications/acknowledge": async (req, res) => {
+    let body = "";
+    req.on("data", (chunk) => {
+      body += chunk.toString();
+    });
+    req.on("end", async () => {
+      try {
+        const { notification_ids } = JSON.parse(body);
+        if (!Array.isArray(notification_ids)) {
+          sendError(res, 400, "notification_ids must be an array");
+          return;
+        }
+        await acknowledgeNotifications(notification_ids);
+        sendJson(res, 200, { acknowledged: notification_ids.length });
+      } catch (err) {
+        sendError(res, 400, `Invalid request: ${err}`);
+      }
+    });
+  },
+};
+
+export const startApiServer = (): void => {
+  const server = createServer(async (req, res) => {
+    const key = `${req.method} ${req.url}`;
+    const handler = handlers[key];
+
+    if (!handler) {
+      res.writeHead(404, { "Content-Type": "application/json" });
+      res.end(JSON.stringify({ error: "Not found" }));
+      return;
+    }
+
+    try {
+      await handler(req, res);
+    } catch (err) {
+      sendError(res, 500, `Internal server error: ${err}`);
+    }
+  });
+
+  server.listen(PORT, () => {
+    console.log(`API server listening on port ${PORT}`);
+  });
+};
