+import { Pool, PoolClient } from "pg";
+import { pool } from "./pool.ts";
+
+type DbClient = Pool | PoolClient;
+
+export interface JobNotification {
+  id: string;
+  job_id: string;
+  payload: string;
+  status: "pending" | "acknowledged";
+  created_at: string;
+}
+
+export const publishJobNotification = async (
+  jobId: string,
+  payload: string,
+  db: DbClient = pool,
+): Promise<void> => {
+  await db.query(
+    "INSERT INTO notifications_outbox (job_id, payload, status) VALUES ($1, $2, 'pending')",
+    [jobId, payload],
+  );
+};
+
+export const getPendingNotifications = async (limit = 100): Promise<JobNotification[]> => {
+  const result = await pool.query(
+    "SELECT id, job_id, payload, status, created_at FROM notifications_outbox WHERE status = 'pending' ORDER BY created_at LIMIT $1",
+    [limit],
+  );
+  return result.rows;
+};
+
+export const acknowledgeNotifications = async (notificationIds: string[]): Promise<void> => {
+  if (notificationIds.length === 0) return;
+  const placeholders = notificationIds.map((_, i) => `$${i + 1}`).join(",");
+  await pool.query(
+    `UPDATE notifications_outbox SET status = 'acknowledged' WHERE id IN (${placeholders})`,
+    notificationIds,
+  );
+};
